# AMP: serves the knowledge base the official launcher would serve; exits once this instance's servers stop.
import http.server, os, sys, threading, time

root, port, srvdir = os.path.realpath(sys.argv[1]), int(sys.argv[2]), os.path.realpath(sys.argv[3]) + os.sep


class Handler(http.server.SimpleHTTPRequestHandler):
    def __init__(self, *a, **k):
        super().__init__(*a, directory=root, **k)

    def log_message(self, *a):
        pass

    def list_directory(self, path):
        self.send_error(404)

    def route(self):
        p = self.path.split('?', 1)[0]
        if p != '/knowledge' and not p.startswith('/knowledge/'):
            self.send_error(404)
            return False
        self.path = p[len('/knowledge'):] or '/'
        if not os.path.isfile(self.translate_path(self.path)):
            self.path = '/index.html'  # site routes like /whats-new are client-side
        return True

    def do_GET(self):
        if self.route():
            super().do_GET()

    def do_HEAD(self):
        if self.route():
            super().do_HEAD()


def servers_running():
    for pid in os.listdir('/proc'):
        try:
            if pid.isdigit() and os.readlink(f'/proc/{pid}/exe').startswith(srvdir):
                return True
        except OSError:
            pass
    return False


for _ in range(30):
    try:
        httpd = http.server.ThreadingHTTPServer(('', port), Handler)
        break
    except OSError:
        time.sleep(1)
else:
    sys.exit(f'[AMP] Knowledge base port {port} is in use')

threading.Thread(target=httpd.serve_forever, daemon=True).start()
print(f'[AMP] Knowledge base serving on port {port}', flush=True)
seen, misses = False, 0
while True:
    time.sleep(2)
    if servers_running():
        seen, misses = True, 0
    else:
        misses += 1
        if misses >= (3 if seen else 60):
            break

# AMP: serves the knowledge base the official launcher would serve; exits once this instance's servers stop.
param([string]$Root, [int]$Port, [string]$ServerDir)
$Root = [IO.Path]::GetFullPath($Root).TrimEnd('\') + '\'
$ServerDir = [IO.Path]::GetFullPath($ServerDir).TrimEnd('\') + '\'
$types = @{ '.html' = 'text/html; charset=utf-8'; '.js' = 'text/javascript'; '.css' = 'text/css'; '.json' = 'application/json'; '.map' = 'application/json'; '.txt' = 'text/plain'; '.webp' = 'image/webp'; '.png' = 'image/png'; '.svg' = 'image/svg+xml'; '.ico' = 'image/x-icon' }

function Send-Response($client) {
    $client.ReceiveTimeout = 5000; $client.SendTimeout = 10000
    $stream = $client.GetStream()
    $reader = New-Object IO.StreamReader($stream)
    $method, $target = $reader.ReadLine() -split ' '
    while ($reader.ReadLine()) { }
    $path = [Uri]::UnescapeDataString(($target -split '\?')[0])
    $file = $null
    if ($path -eq '/knowledge' -or $path.StartsWith('/knowledge/')) {
        $file = [IO.Path]::GetFullPath($Root + $path.Substring(10).TrimStart('/').Replace('/', '\'))
        # site routes like /whats-new are client-side
        if (-not $file.StartsWith($Root) -or -not [IO.File]::Exists($file)) { $file = $Root + 'index.html' }
    }
    if ($file) {
        $code = '200 OK'; $body = [IO.File]::ReadAllBytes($file)
        $type = $types[[IO.Path]::GetExtension($file).ToLower()]; if (-not $type) { $type = 'application/octet-stream' }
    } else {
        $code = '404 Not Found'; $body = [Text.Encoding]::UTF8.GetBytes('Not found'); $type = 'text/plain'
    }
    $head = [Text.Encoding]::ASCII.GetBytes("HTTP/1.1 $code`r`nContent-Type: $type`r`nContent-Length: $($body.Length)`r`nConnection: close`r`n`r`n")
    $stream.Write($head, 0, $head.Length)
    if ($method -ne 'HEAD') { $stream.Write($body, 0, $body.Length) }
}

function Test-ServersRunning {
    [bool](Get-Process ShardsServer, ClusterServer -ErrorAction SilentlyContinue | Where-Object { $_.Path -and $_.Path.StartsWith($ServerDir, 'OrdinalIgnoreCase') })
}

$listener = $null
for ($i = 0; $i -lt 30 -and -not $listener; $i++) {
    try { $l = New-Object Net.Sockets.TcpListener([Net.IPAddress]::Any, $Port); $l.Start(); $listener = $l } catch { Start-Sleep 1 }
}
if (-not $listener) { Write-Output "[AMP] Knowledge base port $Port is in use"; exit 1 }
Write-Output "[AMP] Knowledge base serving on port $Port"
$seen = $false; $misses = 0; $next = [DateTime]::UtcNow
while ($true) {
    if ($listener.Pending()) {
        $client = $listener.AcceptTcpClient()
        try { Send-Response $client } catch { } finally { $client.Close() }
        continue
    }
    if ([DateTime]::UtcNow -ge $next) {
        $next = [DateTime]::UtcNow.AddSeconds(2)
        if (Test-ServersRunning) { $seen = $true; $misses = 0 }
        elseif (++$misses -ge $(if ($seen) { 3 } else { 60 })) { break }
    }
    Start-Sleep -Milliseconds 50
}
$listener.Stop()
